import React, { useState, useRef, useCallback, useEffect } from 'react';
import Webcam from 'react-webcam';
import { attendanceAPI } from './api_service';

import {
  CheckCircle,
  XCircle,
  RefreshCw,
  UserCheck,
  Fingerprint,
  Volume2,
  VolumeX
} from 'lucide-react';

const logger = {
  info: (msg, data) => console.log(`[INFO] ${msg}`, data || ""),
  error: (msg, err) => console.error(`[ERROR] ${msg}`, err || "")
};

const CameraRecognition = () => {
  const webcamRef = useRef(null);

  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);

  /**
   * ================= AUDIO =================
   */
  const playSound = (type) => {
    if (!soundEnabled) return;

    const audio = new Audio(
      type === 'success'
        ? '/sounds/success.mp3'
        : '/sounds/error.mp3'
    );

    audio.play().catch(() => {
      logger.error("Audio failed");
    });
  };

  /**
   * ================= CAMERA CONFIG =================
   */
  const videoConstraints = {
    width: 1280,
    height: 720,
    facingMode: "user"
  };

  /**
   * ================= CLEANUP =================
   */
  useEffect(() => {
    return () => {
      const stream = webcamRef.current?.stream;
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
        logger.info("Camera stopped");
      }
    };
  }, []);

  /**
   * ================= CAPTURE + RECOGNITION =================
   */
  const handleCapture = useCallback(async () => {
    if (!webcamRef.current) {
      setError("Camera not available");
      return;
    }

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const imageSrc = webcamRef.current.getScreenshot();

      if (!imageSrc) {
        throw new Error("Screenshot failed");
      }

      logger.info("Sending image...");

      const response = await attendanceAPI.recognize(imageSrc);

      const data = response?.data;

      /**
       * ================= SAFETY CHECK =================
       */
      if (!data) {
        throw new Error("Empty response from server");
      }

      if (!data.success) {
        throw new Error(data.error || "Recognition failed");
      }

      /**
       * ================= SUCCESS =================
       */
      setResult({
        name: data.student || "Unknown",
        email: data.email || "N/A",
        confidence: data.confidence || 0,
        timestamp: data.timestamp || new Date().toISOString(),
        attendanceId: data.attendance_id || "N/A",
        message: data.message || "Recognized"
      });

      playSound('success');
      logger.info("Recognition success", data.student);

    } catch (err) {
      const msg =
        err?.response?.data?.error ||
        err.message ||
        "Recognition error";

      setError(msg);
      setResult(null);
      playSound('error');

      logger.error("Recognition failed", msg);

    } finally {
      setLoading(false);
    }
  }, [soundEnabled]);

  /**
   * ================= AUTO MODE =================
   */
  useEffect(() => {
    let interval;

    if (autoMode) {
      interval = setInterval(() => {
        if (!loading) {
          handleCapture();
        }
      }, 5000);
    }

    return () => clearInterval(interval);
  }, [autoMode, loading, handleCapture]);

  return (
    <div style={styles.container}>

      {/* HEADER */}
      <div style={styles.header}>
        <h1 style={styles.title}>
          <UserCheck /> Face Recognition
        </h1>

        <button
          onClick={() => setSoundEnabled(!soundEnabled)}
          style={styles.iconBtn}
        >
          {soundEnabled ? <Volume2 /> : <VolumeX />}
        </button>
      </div>

      {/* CAMERA */}
      <div style={styles.cameraBox}>
        <Webcam
          ref={webcamRef}
          audio={false}
          screenshotFormat="image/jpeg"
          videoConstraints={videoConstraints}
          style={styles.webcam}
        />

        {loading && (
          <div style={styles.loadingOverlay}>
            <RefreshCw size={50} className="spin" />
          </div>
        )}
      </div>

      {/* BUTTONS */}
      <div style={styles.actions}>
        <button
          onClick={handleCapture}
          disabled={loading}
          style={{
            ...styles.btn,
            background: loading ? "#94A3B8" : "#4F46E5"
          }}
        >
          <Fingerprint />
          {loading ? "Processing..." : "Recognize"}
        </button>

        <button
          onClick={() => setAutoMode(!autoMode)}
          style={{
            ...styles.btn,
            background: autoMode ? "#10B981" : "#E2E8F0",
            color: autoMode ? "white" : "#1E293B"
          }}
        >
          {autoMode ? "AUTO ON" : "AUTO OFF"}
        </button>
      </div>

      {/* RESULT */}
      {result && (
        <div style={styles.successBox}>
          <CheckCircle color="green" />
          <div>
            <h3>{result.name}</h3>
            <p>{result.email}</p>
            <small>ID: {result.attendanceId}</small>
            <br />
            <small>
              Confidence: {(result.confidence * 100).toFixed(1)}%
            </small>
          </div>
        </div>
      )}

      {/* ERROR */}
      {error && (
        <div style={styles.errorBox}>
          <XCircle />
          <span>{error}</span>
        </div>
      )}
    </div>
  );
};

/**
 * ================= STYLES =================
 */
const styles = {
  container: {
    padding: 20,
    maxWidth: 800,
    margin: "auto"
  },

  header: {
    display: "flex",
    justifyContent: "space-between",
    marginBottom: 20
  },

  title: {
    display: "flex",
    gap: 10,
    alignItems: "center"
  },

  iconBtn: {
    background: "transparent",
    border: "none",
    cursor: "pointer"
  },

  cameraBox: {
    position: "relative",
    borderRadius: 20,
    overflow: "hidden"
  },

  webcam: {
    width: "100%",
    borderRadius: 20
  },

  loadingOverlay: {
    position: "absolute",
    inset: 0,
    background: "rgba(0,0,0,0.4)",
    display: "grid",
    placeItems: "center",
    color: "white"
  },

  actions: {
    display: "flex",
    gap: 10,
    marginTop: 20
  },

  btn: {
    flex: 1,
    padding: 12,
    borderRadius: 10,
    border: "none",
    cursor: "pointer",
    color: "white",
    display: "flex",
    gap: 8,
    justifyContent: "center",
    alignItems: "center"
  },

  successBox: {
    marginTop: 20,
    padding: 15,
    background: "#DCFCE7",
    borderRadius: 10,
    display: "flex",
    gap: 10
  },

  errorBox: {
    marginTop: 20,
    padding: 15,
    background: "#FEE2E2",
    borderRadius: 10,
    display: "flex",
    gap: 10,
    alignItems: "center"
  }
};

export default CameraRecognition;
